/* Витрина импортирует стили побочным эффектом (`import '../src/ds.css'`), а TypeScript
 * про такие модули ничего не знает и отказывается их разрешать. Объявление ниже — не
 * заглушка ради тишины: оно ровно описывает то, чем эти импорты являются, — модулем без
 * значения. Файл появился вместе с типизацией витрины: до неё showcase/ не проверялся
 * вовсе, и первые же четыре ошибки нашлись сразу. */
declare module '*.css';
